import{_ as s,o as t,c as i,a2 as n}from"./chunks/framework.oPQd_6mD.js";const u=JSON.parse('{"title":"Identités, schémas et bases de données","description":"","frontmatter":{},"headers":[],"relativePath":"guide/identites-bases.md","filePath":"guide/identites-bases.md","lastUpdated":null}'),a={name:"guide/identites-bases.md"};function d(o,e,r,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="identites-schemas-et-bases-de-donnees" tabindex="-1">Identités, schémas et bases de données <a class="header-anchor" href="#identites-schemas-et-bases-de-donnees" aria-label="Permalink to &quot;Identités, schémas et bases de données&quot;">​</a></h1><p>Le CLI accepte des <strong>profils</strong> sans inventer une connexion externe ou une session authentifiée :</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">create</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">feathers</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app mon</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">projet </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ui daisyui </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render ssr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">schema zod </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth keycloak </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">db main:postgresql</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">audit:mongodb</span></span></code></pre></div><p>Les fichiers <code>api/config/profile.json</code> et <code>api/config/capabilities.mjs</code> documentent les connexions nommées et bloquent le lancement tant que l&#39;intégration n&#39;a pas été configurée. <strong>Aucune API non protégée n&#39;est activée à la place d&#39;un fournisseur indisponible.</strong></p><table tabindex="0"><thead><tr><th>Option</th><th>État R17-r3</th></tr></thead><tbody><tr><td><code>--auth none</code></td><td>Laboratoire en mémoire opérationnel</td></tr><tr><td><code>--auth jwt</code></td><td>Profil d&#39;intégration, non activé automatiquement</td></tr><tr><td><code>--auth oauth2</code></td><td>Profil fournisseur OAuth2, flux externe à configurer</td></tr><tr><td><code>--auth oidc</code>, <code>--auth keycloak</code></td><td>Profils OIDC ; PKCE, JWKS, audience, issuer, mapping des rôles à certifier</td></tr><tr><td><code>--db main:memory</code></td><td>Service en mémoire opérationnel</td></tr><tr><td><code>--db NOM:mongodb</code></td><td>Profil MongoDB ; client et identifiants à configurer</td></tr><tr><td><code>--db NOM:postgresql</code> (ou <code>mariadb</code>, <code>mysql</code>, <code>sqlite</code>)</td><td>Profil Knex ; pilote, migrations et connexions à configurer</td></tr><tr><td><code>--schema typebox</code>, <code>--schema json</code> ou <code>--schema zod</code></td><td>Modèle de validation générable pour les nouveaux services</td></tr></tbody></table><p>Dans les exemples, <code>NOM</code> désigne un nom de connexion que vous choisissez, par exemple <code>main</code>. Les options de schéma et de base se choisissent individuellement ; les profils externes ne créent aucune connexion opérationnelle.</p><p>Ne mettez jamais les secrets JWT, chaînes de connexion, clés privées ou secrets OAuth dans <code>.env.example</code>, VitePress ou Git. Utilisez un magasin de secrets externe et des politiques de rôles explicites. La protection des services ne se limite pas à la vérification d&#39;identité.</p><p>Pour un déploiement public, validez séparément les sessions, la rotation des clés, les contrôles d&#39;accès, CSRF/CORS, la journalisation et les droits sur chaque service.</p>',8)])])}const k=s(a,[["render",d]]);export{u as __pageData,k as default};
